import { gs, GlideRecord } from '@servicenow/glide';
export function detectDuplicatePartner(current, previous) {
    var regNum = current.getValue('registration_number');
    var pan = current.getValue('pan');
    if (!regNum || !pan)
        return;
    var gr = new GlideRecord('x_2248447_csr_ma_2_partner');
    gr.addQuery('registration_number', regNum);
    gr.addQuery('pan', pan);
    gr.addQuery('sys_id', '!=', current.getUniqueValue());
    gr.query();
    if (gr.next()) {
        current.setValue('duplicate_flag', true);
        gs.addErrorMessage('Duplicate partner detected: registration number and PAN combination already exists for ' + gr.getValue('name'));
        current.setAbortAction(true);
    }
}
export function recalcPartnerScore(current, previous) {
    var overdue = parseInt(current.getValue('overdue_reports')) || 0;
    var lapses = parseInt(current.getValue('document_lapses')) || 0;
    var score = 100 - (10 * overdue) - (20 * lapses);
    if (score < 0)
        score = 0;
    current.setValue('partner_score', score);
}
export function checkCorrectionLimit(current, previous) {
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');
    if (newStatus === 'draft' && (oldStatus === 'pending_compliance' || oldStatus === 'pending_manager')) {
        var attempts = parseInt(current.getValue('correction_attempts')) || 0;
        attempts++;
        current.setValue('correction_attempts', attempts);
        var limit = parseInt(gs.getProperty('x_2248447_csr_ma_2.partner_correction_attempt_limit')) || 3;
        if (attempts >= limit) {
            current.setValue('status', 'rejected');
            gs.addErrorMessage('Partner registration rejected: maximum correction attempts (' + limit + ') exceeded.');
        }
    }
}
export function autoApproveContactChange(current, previous) {
    var changeType = current.getValue('change_type');
    if (changeType === 'contact') {
        current.setValue('status', 'auto_approved');
    }
}
